            "child_gender": 59,
            "parent_gender": 60,
            "keywords": [4086, 86],
            "meta_keywords": "miyaning rivojlanishi, harakatlanish ko‘nikmalari",
            "cover_image": {
                "url": "https://bebbo.app/sites/default/files/styles/content_1200xh_/public/2021-08/markus-spiske-nvkq1kxherc-unsplash.webp?itok=H8iKKiez",
                "name": "© Markus Spiske  ",
                "alt": "toddler playing at home"
            },
