            "meta_keywords": "чистка зубов, чистка зубов",
            "cover_image": {
                "url": "https://bebbo.app/sites/default/files/styles/content_1200xh_/public/2021-08/alex-7byfi6fpi90-unsplash.webp?itok=6pyWW_8G",
                "name": "© Alex on Unsplash.",
                "alt": "teeth"
            },
