            "parent_gender": 60,
            "keywords": [981, 626, 526, 201, 196],
            "meta_keywords": "nutq rivojlanishi, logopediya/nutq terapiyasi, nutq rivojlanishining kechikishi, nutq ko‘nikmalari, nutq ko‘nikmalarini rivojlantirish",
